def list_coin_library(query: str | None = None, limit: int | None = None) -> list[dict[str, object]]:
    normalized_query = str(query or "").strip().lower()
    output = []
    for item in COIN_LIBRARY:
        terms = [
            str(item.get("symbol") or ""),
            str(item.get("base_asset") or ""),
            str(item.get("name") or ""),
            str(item.get("category") or ""),
            *[str(alias) for alias in item.get("aliases", [])],
        ]
        if normalized_query and not any(normalized_query in term.lower() for term in terms):
            continue
        output.append(
            {
                **item,
                "quote_asset": "USDT",
                "display_name": f"{item['name']} · {item['symbol']}",
            }
        )
    return output[:limit] if limit else output
